// export default HostelAdmin;

// Existing functionality :-

  // - Display hostel rooms.
  // - Display booking requests.
  // - Accept booking requests.
  // - Reject booking requests.
  // - Filter requests by status.

  // New requirements :- 
  // 1. Fix the room occupancy update.
  // 2. Never allow room occupancy to exceed capacity.
  // 3. Prevent accepting an already accepted or rejected request.
  // 4. Prevent rejecting an already processed request.
  // 5. Fix the booking status filtering.
  // 6. Display the number of available beds across all rooms.
  // 7. Display the total number of pending requests.
  // 8. Add a message when no requests match the selected filter.
  // 9. Do not directly mutate existing React state.
  // 10. Preserve all existing functionality.

import { useState } from "react";
function Task9() {
  const [rooms, setRooms] = useState([
    { id: 1, room: "101", capacity: 3, occupied: 1 },
    { id: 2, room: "102", capacity: 2, occupied: 2 },
    { id: 3, room: "103", capacity: 4, occupied: 1 }
  ]);

  const [requests, setRequests] = useState([
    { id: 1, name: "Rahul", roomId: 1, status: "Pending" },
    { id: 2, name: "Priya", roomId: 2, status: "Pending" },
    { id: 3, name: "Arjun", roomId: 3, status: "Pending" }
  ]);

  const [filter, setFilter] = useState("All");


  function approveRequest(requestId) {
    const request = requests.find(
      (item) => item.id === requestId
    );
    if(request.status==="Accepted"){
        alert("Already Accepted")
        return;
    }
    const updatedRequests = requests.map((item) => {
      if (item.id === requestId) {
        if(item.status !== "Accepted"){
            return {...item,status:"Accepted"}
        }
        else{
            alert("already Accepted");
            // return;
        }
      }

      return item;
    });

    setRequests(updatedRequests);


    // console.log("request",request)
    const updatedRooms = rooms.map((room) => {
      if (room.id === request.roomId) {
        if(room.occupied<room.capacity){
            room.occupied=room.occupied+1;
        }
        else{
            alert("Sorry Your Selected Rooms are full! you can choose another Room")
        }
      }

      return room;
    });

    setRooms(updatedRooms);

  }


  function rejectRequest(requestId) {
    const updatedRequests = requests.map((item) => {
      if (item.id === requestId) {
        if(item.status!=="Rejected"){
            return { ...item, status: "Rejected" };
        }
        else{
            alert("Already Rejected")
            return;
        }
      }

      return item;
    });

    setRequests(updatedRequests);
  }

  const filteredRequests = requests.filter((request) => {
    return filter === "All" || request.status === filter;
  });

  return (
    <div>
      <h2>Hostel Admin Dashboard</h2>

      <h3>Rooms</h3>

      {rooms.map((room) => (
        <div key={room.id}>
          <p>Room: {room.room}</p>
          <p>Occupied: {room.occupied}</p>
          <p>Available: {room.capacity - room.occupied}</p><hr></hr>
        </div>
      ))}

      <h3>Booking Requests</h3>
      <p>Total availble Beds : <strong>{rooms.reduce((acc,room)=>{
        return acc+=room.capacity-room.occupied;
      },0)}</strong></p>
      <p>Total no.of Pending Requests : <strong>{requests.filter((request)=>{
            return request.status==="Pending"
      }).length}</strong></p>

      <button onClick={() => setFilter("All")}>All</button>
      <button onClick={() => setFilter("Pending")}>Pending</button>
      <button onClick={() => setFilter("Accepted")}>Accepted</button>
      <button onClick={() => setFilter("Rejected")}>Rejected</button>

      {filteredRequests.length>0 ? filteredRequests.map((request) => (
        <div key={request.id}>
          <p>{request.name}</p>
          <p>Status: {request.status}</p>
          <button onClick={() => approveRequest(request.id)}>Accept</button>
          <button onClick={() => rejectRequest(request.id)}>Reject</button>
        </div>
      )):<h4>No Items Found</h4>}
    </div>
  );
}

export default Task9;